GROUPS=[{'QB'},{'RB'},{'WR'},{'TE'},{'OT','G','C'},{'EDGE','DT','LB'},{'LB','EDGE'},{'CB','S'},{'S','CB'},{'K'},{'P'}]
def load():
  d={}
  lines=[l for l in STARS.strip().split('\n') if l.strip()]
  for gi,line in enumerate(lines):
    for part in line.split('|'):
      part=part.strip()
      if ':' not in part: continue
      n,v=part.rsplit(':',1)
      try: d[n.strip()]=(int(v),GROUPS[gi])
      except: pass
  return d
